import{_ as t,o as i,c as s,a0 as a}from"./chunks/framework.DYS8d9tm.js";const u=JSON.parse('{"title":"🏗️ Build, Release & Local Push Infrastructure","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/build_and_push_infra.md","filePath":"deployment/build_and_push_infra.md"}'),l={name:"deployment/build_and_push_infra.md"};function o(n,e,r,d,c,h){return i(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="🏗️-build-release-local-push-infrastructure" tabindex="-1">🏗️ Build, Release &amp; Local Push Infrastructure <a class="header-anchor" href="#🏗️-build-release-local-push-infrastructure" aria-label="Permalink to &quot;🏗️ Build, Release &amp; Local Push Infrastructure&quot;">​</a></h1><p>WealthFam operates a multi-repository workspace orchestrated via the <code>Infra</code> repository. This document details the CLI tooling, multi-repo release workflow, Docker Buildx pipeline, and local deployment infrastructure.</p><hr><h2 id="🧭-multi-repo-architecture-tooling" tabindex="-1">🧭 Multi-Repo Architecture &amp; Tooling <a class="header-anchor" href="#🧭-multi-repo-architecture-tooling" aria-label="Permalink to &quot;🧭 Multi-Repo Architecture &amp; Tooling&quot;">​</a></h2><p>The WealthFam ecosystem spans several distinct repositories:</p><ul><li><strong><code>Backend</code></strong>: FastAPI core engine &amp; financial ledger</li><li><strong><code>Web-App</code></strong>: Vue 3 + Vite frontend dashboard</li><li><strong><code>Parser</code></strong>: Ingestion microservice &amp; pattern engine</li><li><strong><code>Admin-Backend</code></strong>: FastAPI telemetry, endpoint SLA, parser studio &amp; brand logo API (<code>:8002</code>)</li><li><strong><code>Admin-Web</code></strong>: Vue 3 + Vite enterprise admin console (<code>:8080</code> / <code>:5174</code>)</li><li><strong><code>Mobile-App</code></strong>: Flutter Android client</li><li><strong><code>Infra</code></strong>: Container orchestration, build scripts, and CLI tooling</li><li><strong><code>Docs</code></strong>: VitePress documentation hub</li></ul><h3 id="unified-workspace-cli-wf-sh" tabindex="-1">Unified Workspace CLI (<code>wf.sh</code>) <a class="header-anchor" href="#unified-workspace-cli-wf-sh" aria-label="Permalink to &quot;Unified Workspace CLI (`wf.sh`)&quot;">​</a></h3><p>At the workspace root (or within <code>Infra/</code>), the <code>wf.sh</code> command provides an interactive, menu-driven CLI for all lifecycle operations:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./Infra/wf.sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [command]</span></span></code></pre></div><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">Action</th><th style="text-align:left;">Implementation</th></tr></thead><tbody><tr><td style="text-align:left;"><code>./Infra/wf.sh status</code></td><td style="text-align:left;">Scans git branch status and uncommitted changes across all sub-repos</td><td style="text-align:left;"><code>Infra/scripts/cli/status.sh</code></td></tr><tr><td style="text-align:left;"><code>./Infra/wf.sh sync</code></td><td style="text-align:left;">Pulls latest changes across all local repositories</td><td style="text-align:left;"><code>Infra/scripts/cli/sync.sh</code></td></tr><tr><td style="text-align:left;"><code>./Infra/wf.sh dev</code></td><td style="text-align:left;">Launches local development services (Backend, Frontend, Parser)</td><td style="text-align:left;"><code>Infra/scripts/cli/dev.sh</code></td></tr><tr><td style="text-align:left;"><code>./Infra/wf.sh test</code></td><td style="text-align:left;">Runs comprehensive test suites across Backend, Mobile, and Web</td><td style="text-align:left;"><code>Infra/scripts/cli/test.sh</code></td></tr><tr><td style="text-align:left;"><code>./Infra/wf.sh release</code></td><td style="text-align:left;">Pre-flight check, version bumping, git commit/tag, and multi-repo push</td><td style="text-align:left;"><code>Infra/scripts/cli/release.sh</code></td></tr></tbody></table><hr><h2 id="🚀-release-management-pipeline-release-sh" tabindex="-1">🚀 Release Management Pipeline (<code>release.sh</code>) <a class="header-anchor" href="#🚀-release-management-pipeline-release-sh" aria-label="Permalink to &quot;🚀 Release Management Pipeline (`release.sh`)&quot;">​</a></h2><p>The release workflow guarantees cross-repository synchronization and atomic version bumping:</p><ol><li><strong>Pre-Flight Scans</strong>: Discovers all active sub-repos and flags untracked/uncommitted changes.</li><li><strong>Version Governance (<code>version.json</code>)</strong>: <ul><li>Semantic versioning: <code>major.minor.patch</code></li><li>Build string format: <code>v&lt;MAJOR&gt;.&lt;MINOR&gt;.&lt;PATCH&gt;-b&lt;GIT_HASH&gt;-&lt;YYYYMMDD&gt;</code></li></ul></li><li><strong>Automated Testing</strong>: Runs unit tests and linter pre-flights before tagging.</li><li><strong>Multi-Repo Tagging &amp; Push</strong>: Commits changes with structured release notes, tags the commit, and pushes to remote origins.</li></ol><hr><h2 id="🐳-docker-multi-arch-buildx-pipeline-build-and-push-sh" tabindex="-1">🐳 Docker Multi-Arch Buildx Pipeline (<code>build_and_push.sh</code>) <a class="header-anchor" href="#🐳-docker-multi-arch-buildx-pipeline-build-and-push-sh" aria-label="Permalink to &quot;🐳 Docker Multi-Arch Buildx Pipeline (`build_and_push.sh`)&quot;">​</a></h2><p>Located at <code>Infra/scripts/deploy/build_and_push.sh</code>, this script builds unified, production-grade container images supporting both <code>linux/amd64</code> (cloud/server) and <code>linux/arm64</code> (Raspberry Pi, Apple Silicon, ARM NAS).</p><h3 id="execution" tabindex="-1">Execution <a class="header-anchor" href="#execution" aria-label="Permalink to &quot;Execution&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Infra/scripts/deploy/build_and_push.sh</span></span></code></pre></div><h3 id="build-process-workflow" tabindex="-1">Build Process Workflow <a class="header-anchor" href="#build-process-workflow" aria-label="Permalink to &quot;Build Process Workflow&quot;">​</a></h3><ol><li><strong>Environment Detection</strong>: Resolves workspace directories (<code>Backend</code>, <code>Parser</code>, <code>Web-App</code>, <code>Admin-Backend</code>, <code>Admin-Web</code>, <code>Infra/docker/Dockerfile</code>).</li><li><strong>Tag Generation</strong>: <ul><li>Queries <code>Infra/version.json</code> for major, minor, patch versions.</li><li>Extracts current Git SHA and date.</li><li>Generates dual tags: <code>wglabz/wealthfam:v&lt;VERSION&gt;-b&lt;HASH&gt;-&lt;DATE&gt;</code> and <code>wglabz/wealthfam:latest</code>.</li></ul></li><li><strong>Multi-Architecture Build (<code>docker buildx</code>)</strong>: <ul><li>Creates/reuses the <code>wealthfam-builder</code> containerized builder instance:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> buildx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wealthfam-builder</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --use</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --driver</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-container</span></span></code></pre></div></li><li>Invokes <code>docker buildx build --platform linux/amd64,linux/arm64 --push</code> to compile and push directly to Docker Hub.</li></ul></li></ol><hr><h2 id="🏠-local-push-server-deployment-deploy-to-pi-sh" tabindex="-1">🏠 Local Push &amp; Server Deployment (<code>deploy_to_pi.sh</code>) <a class="header-anchor" href="#🏠-local-push-server-deployment-deploy-to-pi-sh" aria-label="Permalink to &quot;🏠 Local Push &amp; Server Deployment (`deploy_to_pi.sh`)&quot;">​</a></h2><p>For self-hosters deploying to local servers (e.g. Raspberry Pi, Unraid, TrueNAS, Home Server):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Infra/scripts/deploy/deploy_to_pi.sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [PI_HOST]</span></span></code></pre></div><h3 id="what-it-does" tabindex="-1">What It Does: <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What It Does:&quot;">​</a></h3><ol><li>Verifies SSH connectivity to the target host.</li><li>Syncs <code>docker-compose.yml</code>, environment configurations, and persistent volume definitions.</li><li>Pulls the latest multi-arch Docker image matching the target hardware architecture (<code>linux/arm64</code> or <code>linux/amd64</code>).</li><li>Performs zero-downtime container recreation:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker-compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker-compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --remove-orphans</span></span></code></pre></div></li><li>Executes automated health checks against <code>/health</code> and <code>/api/v1/health</code>.</li></ol>',27)])])}const g=t(l,[["render",o]]);export{u as __pageData,g as default};
